101	// Internal rendering helpers
102	// ---------------------------------------------------------------------------
103	
104	/**
105	 * Returns the canonical role label for a LangChain message type string.
106	 * Mirrors `_msg_role()` in `dialogue_writer.py`.
107	 */
108	function msgRole(type: string): string {
109	  switch (type.toLowerCase()) {
110	    case 'human':
111	    case 'humanmessage':
112	      return 'Human';
113	    case 'ai':
114	    case 'aimessage':
115	    case 'aimessagechunk':
116	      return 'Assistant';
117	    case 'tool':
118	    case 'toolmessage':
119	      return 'Tool Result';
120	    case 'system':
121	    case 'systemmessage':
122	      return 'System';
123	    default: {
124	      // Strip trailing "message"/"messagechunk" suffix, capitalise first char.
125	      const base = type.toLowerCase()
126	        .replace(/messagechunk$/, '')
127	        .replace(/message$/, '');
128	      return base ? base.charAt(0).toUpperCase() + base.slice(1) : 'Message';
129	    }
130	  }
131	}
132	
133	/**
134	 * Renders a content value (string or list-of-blocks) to a plain string
135	 * suitable for Markdown body text.
136	 * Mirrors `_render_content()` in `dialogue_writer.py`.
137	 */
138	function renderContent(content: string | ContentBlock[] | null | undefined): string {
139	  if (content === undefined || content === null) return '';
140	  if (typeof content === 'string') return content;
141	  if (Array.isArray(content)) {
142	    const parts: string[] = [];
143	    for (const block of content) {
144	      if (typeof block === 'string') {
145	        parts.push(block);
146	      } else if (block && typeof block === 'object') {
147	        const btype = block.type ?? '';
148	        if (btype === 'text') {
149	          parts.push(typeof block.text === 'string' ? block.text : '');
150	        } else if (REDUNDANT_BLOCK_TYPES.has(btype)) {
151	          // Anthropic streaming-only block types — always redundant with
152	          // `tool_calls` / `tool_call_chunks`; skip as a defence-in-depth filter.
153	          // (intentional no-op — block is skipped)
154	        } else {
155	          // Genuinely non-text, non-tool blocks (e.g. `image`) — rendered as
156	          // compact JSON fences for the Markdown debug renderer.
157	          parts.push('```json\n' + JSON.stringify(block, null, 2) + '\n```');
158	        }
159	      } else {
160	        parts.push(String(block));
161	      }
162	    }
163	    return parts.filter(Boolean).join('\n\n');
164	  }
165	  return String(content);
166	}
167	
168	/**
169	 * Renders a list of merged tool calls as fenced Markdown code blocks.
170	 * Mirrors `_render_tool_calls()` in `dialogue_writer.py`.
171	 *
172	 * **Unparseable args fallback contract:**
173	 * When a tool call's accumulated `args` string is not valid JSON (e.g. because
174	 * the stream was truncated mid-token), `JSON.parse()` throws and the raw arg
175	 * string is used as-is.  The rendered output places this raw string directly
176	 * inside a ` ```json ` fence without any further transformation.  This means
177	 * the rendered block will contain partial JSON rather than a pretty-printed
178	 * object.  Consumers should treat a ` ```json ` block that is not valid JSON
179	 * as an indicator of a truncated or incomplete stream capture.
180	 */
181	function renderToolCalls(toolCalls: MergedToolCall[]): string {
182	  const blocks: string[] = [];
183	  for (const tc of toolCalls) {
184	    const name = tc.name || 'unknown_tool';
185	    const tcId = tc.id || '';
186	    const header = `**Tool call:** \`${name}\`` + (tcId ? ` (id: \`${tcId}\`)` : '');
187	
188	    let argsObj: unknown = {};
189	    try {
190	      argsObj = tc.args ? JSON.parse(tc.args) : {};
191	    } catch {
192	      // Treat unparseable args as a raw string.
193	      argsObj = tc.args;
194	    }
195	    const body = '```json\n' + JSON.stringify(argsObj, null, 2) + '\n```';
196	    blocks.push(`${header}\n\n${body}`);
197	  }
198	  return blocks.join('\n\n');
199	}
200	
201	// ---------------------------------------------------------------------------
202	// Markdown rendering
203	// ---------------------------------------------------------------------------
204	
205	/**
206	 * Renders a namespace block to Markdown lines.
207	 *
208	 * For the main agent (nsKey === '') the messages are rendered without an extra
209	 * namespace heading.  For sub-agents a `### Subagent: {label}` heading is
210	 * prepended so the reader can easily identify the agent boundary.
211	 */
212	function renderNamespaceBlock(
213	  nsKey: NamespaceKey,
214	  messages: MergedMessage[],
215	  isSubagent: boolean,
216	): string[] {
217	  const lines: string[] = [];
218	
219	  if (isSubagent) {
220	    lines.push(`### Subagent: ${namespaceLabel(nsKey)}`);
221	    lines.push('');
222	  }
223	
224	  for (const msg of messages) {
225	    const role = msgRole(msg.type);
226	    lines.push(`## ${role}`);
227	    lines.push('');
228	
229	    const contentStr = renderContent(msg.content);
230	    if (contentStr) {
231	      lines.push(contentStr);
232	      lines.push('');
233	    }
234	
235	    if (msg.tool_calls.length > 0) {
236	      lines.push(renderToolCalls(msg.tool_calls));
237	      lines.push('');
238	    }
239	  }
240	
241	  return lines;
242	}
243	
244	/**
245	 * Collects aggregated token usage across all namespaces and messages.
246	 */
247	function collectTotalUsage(
248	  nsMap: Map<NamespaceKey, MergedMessage[]>,
249	): Record<string, number> | null {
250	  const totals: Record<string, number> = {};

251	  for (const messages of nsMap.values()) {
252	    for (const msg of messages) {
253	      for (const [key, value] of Object.entries(msg.usage_metadata)) {
254	        if (typeof value === 'number') {
255	          totals[key] = (totals[key] ?? 0) + value;
256	        }
257	      }
258	    }
259	  }
260	  return Object.keys(totals).length > 0 ? totals : null;
261	}
262	
263	// ---------------------------------------------------------------------------
264	// Public API
265	// ---------------------------------------------------------------------------
266	
267	/**
268	 * Parses a JSONL chunk file and renders its contents to a Markdown string
269	 * structurally consistent with the orchestrator's `serialize_messages_to_markdown()`
270	 * format.
271	 *
272	 * @param jsonlContent  Raw JSONL string (e.g. the content of a `.jsonl` chunk file).
273	 * @returns             A Markdown document string (always ends with a trailing newline).
274	 */
275	export function renderChunksToMarkdown(jsonlContent: string): string {
276	  // --- Parse JSONL content (header validation + line parsing) ---
277	  const records = parseJsonlContent(jsonlContent);
278	
279	  // --- Accumulate chunks into merged messages per namespace ---
280	  const nsMap = accumulateChunks(records);
281	
282	  // --- Build output lines ---
283	  const lines: string[] = [
284	    '# Dialogue — streaming capture',
285	    '',
286	    '| Field | Value |',
287	    '| ----- | ----- |',
288	    '| Format | `chunks` |',
289	    '',
290	  ];
291	
292	  if (nsMap.size === 0) {
293	    lines.push('*No messages recorded.*');
294	    return lines.join('\n') + '\n';
295	  }
296	
297	  // Render main-agent namespace first (empty key), then sub-agents in insertion order.
298	  const mainMessages = nsMap.get('');
299	  if (mainMessages && mainMessages.length > 0) {
300	    lines.push(...renderNamespaceBlock('', mainMessages, false));
301	  }
302	
303	  for (const [nsKey, messages] of nsMap.entries()) {
304	    if (nsKey === '') continue; // already rendered above
305	    if (messages.length > 0) {
306	      lines.push(...renderNamespaceBlock(nsKey, messages, true));
307	    }
308	  }
309	
310	  // --- Token-usage footer ---
311	  const usage = collectTotalUsage(nsMap);
312	  if (usage) {
313	    lines.push('---');
314	    lines.push('');
315	    lines.push('## Token Usage');
316	    lines.push('');
317	    lines.push('| Metric | Count |');
318	    lines.push('| ------ | ----- |');
319	    for (const key of Object.keys(usage).sort()) {
320	      const label = key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
321	      lines.push(`| ${label} | ${usage[key]} |`);
322	    }
323	    lines.push('');
324	  }
325	
326	  return lines.join('\n') + '\n';
327	}
328	
329	// ---------------------------------------------------------------------------
330	// Dialogue rendering — private helpers
331	// ---------------------------------------------------------------------------
332	
333	/**
334	 * Builds a map from toolCallId → toolName by scanning all AI messages across
335	 * all namespaces in the accumulated message map.
336	 */
337	function buildToolCallIndex(
338	  nsMap: Map<NamespaceKey, MergedMessage[]>,
339	): Map<string, string> {
340	  const index = new Map<string, string>();
341	  for (const messages of nsMap.values()) {
342	    for (const msg of messages) {
343	      for (const tc of msg.tool_calls) {
344	        if (tc.id) {
345	          index.set(tc.id, tc.name);
346	        }
347	      }
348	    }
349	  }
350	  return index;
351	}
352	
353	/**
354	 * Builds a map from toolCallId → { toolName, content } by scanning all
355	 * ToolMessages across all namespaces.  Only stores entries for tools whose
356	 * rendering rule needs inline results (currently `execute` and `task`).
357	 */
358	function buildToolResultIndex(
359	  nsMap: Map<NamespaceKey, MergedMessage[]>,
360	  toolCallIndex: Map<string, string>,
361	): Map<string, { toolName: string; content: string }> {
362	  const index = new Map<string, { toolName: string; content: string }>();
363	
364	  for (const messages of nsMap.values()) {
365	    for (const msg of messages) {
366	      const msgType = msg.type.toLowerCase();
367	      if (msgType !== 'tool' && msgType !== 'toolmessage') continue;
368	      const tcId = msg.tool_call_id;
369	      if (!tcId) continue;
370	
371	      const toolName = toolCallIndex.get(tcId);
372	      if (!toolName || !INLINE_RESULT_TOOLS.has(toolName)) continue;
373	
374	      const content = renderContent(msg.content);
375	      index.set(tcId, { toolName, content });
376	    }
377	  }
378	  return index;
379	}
380	
381	/**
382	 * Strips a leading `cd … &&` prefix from a shell command, takes the first
383	 * meaningful command token, and truncates to ≤ 80 characters with `…`.
384	 */
385	function abbreviateCommand(command: string): string {
386	  // Strip leading `cd <dir> &&` or `cd "<dir>" &&` prefix (possibly chained).
387	  let cmd = command.trim();
388	  cmd = cmd.replace(/^(cd\s+(?:"[^"]*"|'[^']*'|\S+)\s*&&\s*)+/i, '').trim();
389	
390	  // Truncate to 80 chars with ellipsis if needed.
391	  if (cmd.length > 80) {
392	    return cmd.slice(0, 79) + '…';
393	  }
394	  return cmd;
395	}
396	
397	/**
398	 * Extracts the last meaningful output line and exit-code success flag from a
399	 * ToolMessage content string produced by `execute`.
400	 *
401	 * Content format (approximate):
402	 *   <output lines…>
403	 *   [Command succeeded with exit code 0]   ← or "failed with exit code N"
404	 *
405	 * Returns null if content is empty or no meaningful line exists.
406	 *
407	 * @remarks
408	 * **Default-success behaviour.**
409	 * When no `[Command succeeded/failed…]` footer line is found in the content,
410	 * the function defaults to `success = true`.  This is intentional: commands
411	 * that produce output without a footer line are assumed to have succeeded (e.g.
412	 * tools that emit a result without a trailing exit-code annotation).  The
413	 * sibling formatter `formatExecuteDetail` renders ✓ or ✗ based on this value.
414	 *
415	 * **Summary truncation.**
416	 * The returned `summary` string is capped at 120 characters (with a trailing
417	 * `…` when truncated) to prevent unwieldy `↳` lines in the dialogue output.
418	 * The full content is always available in the raw JSONL.
419	 */
420	function extractExecuteResult(
421	  content: string,
422	): { summary: string; success: boolean } | null {
423	  const lines = content.split('\n').map(l => l.trim());
424	
425	  // Find the exit-code footer line.
426	  let footerIdx = -1;
427	  let success = true;
428	  for (let i = lines.length - 1; i >= 0; i--) {
429	    const line = lines[i] ?? '';
430	    const match = line.match(/^\[Command\s+(succeeded|failed)\s+with\s+exit\s+code\s+(\d+)\]$/i);
431	    if (match) {
432	      footerIdx = i;
433	      success = match[1]?.toLowerCase() === 'succeeded';
434	      break;
435	    }
436	  }
437	
438	  // Collect all non-empty, non-footer lines.
439	  const outputLines = lines.filter(
440	    (l, i) => l && i !== footerIdx,
441	  );
442	
443	  if (outputLines.length === 0) return null;
444	
445	  let summary = outputLines[outputLines.length - 1]!;
446	  const MAX_SUMMARY_LENGTH = 120;
447	  if (summary.length > MAX_SUMMARY_LENGTH) {
448	    summary = summary.slice(0, MAX_SUMMARY_LENGTH - 1) + '…';
449	  }
450	  return { summary, success };

451	}
452	
453	// ---------------------------------------------------------------------------
454	// Dialogue rendering — per-family formatter helpers
455	// ---------------------------------------------------------------------------
456	
457	/**
458	 * Formats a `↳ [filename](file_path)` detail line for file tools
459	 * (`edit_file`, `write_file`, `read_file`).
460	 */
461	function formatFileToolDetail(args: unknown): string[] {
462	  if (!args || typeof args !== 'object' || Array.isArray(args)) return [];
463	  const a = args as Record<string, unknown>;
464	
465	  // edit_file / write_file use `file_path`; read_file also uses `file_path`.
466	  const filePath =
467	    typeof a['file_path'] === 'string' ? a['file_path'] :
468	    typeof a['path'] === 'string' ? a['path'] :
469	    null;
470	
471	  if (!filePath) return [];
472	
473	  const filename = filePath.split('/').pop() ?? filePath;
474	  return [`↳ [${filename}](${filePath})`];
475	}
476	
477	/**
478	 * Formats `↳ \`abbreviated_command\`` and an optional result line for `execute`.
479	 */
480	function formatExecuteDetail(
481	  args: unknown,
482	  resultEntry?: { toolName: string; content: string },
483	): string[] {
484	  const lines: string[] = [];
485	  if (args && typeof args === 'object' && !Array.isArray(args)) {
486	    const command = (args as Record<string, unknown>)['command'];
487	    if (typeof command === 'string') {
488	      lines.push('↳ `' + abbreviateCommand(command) + '`');
489	    }
490	  }
491	  if (resultEntry) {
492	    const extracted = extractExecuteResult(resultEntry.content);
493	    if (extracted) {
494	      const tick = extracted.success ? '✓' : '✗';
495	      // extracted.summary is guaranteed ≤ 120 chars (truncated by extractExecuteResult).
496	      lines.push(`↳ ${extracted.summary} ${tick}`);
497	    }
498	  }
499	  return lines;
500	}
501	
502	/**
503	 * Formats `↳ Sub-agent: **subagent_type**` and an optional first-result-line for `task`.
504	 */
505	function formatTaskDetail(
506	  args: unknown,
507	  resultEntry?: { toolName: string; content: string },
508	): string[] {
509	  const lines: string[] = [];
510	  if (args && typeof args === 'object' && !Array.isArray(args)) {
511	    const subagentType = (args as Record<string, unknown>)['subagent_type'];
512	    if (typeof subagentType === 'string') {
513	      lines.push(`↳ Sub-agent: **${subagentType}**`);
514	    }
515	  }
516	  if (resultEntry) {
517	    const firstLine = resultEntry.content
518	      .split('\n')
519	      .map(l => l.trim())
520	      .find(l => l.length > 0);
521	    if (firstLine) {
522	      lines.push(`↳ ${firstLine}`);
523	    }
524	  }
525	  return lines;
526	}
527	
528	/**
529	 * Formats `write_todos` as a compact checklist.
530	 *
531	 * The args `todos` field is an array of `{ content: string; status: string }`
532	 * objects.  Each item is rendered as `- [x] content` (completed) or
533	 * `- [ ] content` (pending / in_progress).
534	 *
535	 * @remarks
536	 * **Return-shape divergence from sibling formatters.**
537	 * Unlike `formatFileToolDetail`, `formatExecuteDetail`, `formatTaskDetail`, and
538	 * `formatLedgerToolDetail` — which all return `'↳ …'`-prefixed strings —
539	 * this function returns raw Markdown list items (`'- [x] …'` / `'- [ ] …'`).
540	 *
541	 * This is intentional: `write_todos` renders a visual checklist, not a
542	 * summary line.  The `getToolDetailLines` dispatcher pushes return values
543	 * verbatim into the output line buffer, so the rendered Markdown is correct.
544	 *
545	 * If you add a new formatter to this family, follow the `'↳ …'` convention
546	 * unless the tool's output is inherently list-shaped.  Do **not** model a new
547	 * formatter on `formatWriteTodosDetail` for the general case.
548	 */
549	function formatWriteTodosDetail(args: unknown): string[] {
550	  if (!args || typeof args !== 'object' || Array.isArray(args)) return [];
551	  const a = args as Record<string, unknown>;
552	  const todos = a['todos'];
553	  if (!Array.isArray(todos) || todos.length === 0) return [];
554	
555	  return todos.map((todo: unknown) => {
556	    if (!todo || typeof todo !== 'object' || Array.isArray(todo)) return '- [ ] (unknown)';
557	    const t = todo as Record<string, unknown>;
558	    const content = typeof t['content'] === 'string' ? t['content'] : '(unknown)';
559	    const status = typeof t['status'] === 'string' ? t['status'] : '';
560	    const checked = status === 'completed' ? 'x' : ' ';
561	    return `- [${checked}] ${content}`;
562	  });
563	}
564	
565	/**
566	 * Formats contextual `↳ …` detail lines for `ledger_*` tools.
567	 *
568	 * Tools are split into mutation and query families; each has its own detail
569	 * format.  Unrecognised ledger tools emit no detail line (but the header is
570	 * always emitted by the caller).
571	 */
572	function formatLedgerToolDetail(name: string, args: unknown): string[] {
573	  const a = (args && typeof args === 'object' && !Array.isArray(args))
574	    ? (args as Record<string, unknown>)
575	    : {};
576	
577	  const wp = typeof a['work_package_id'] === 'string' ? a['work_package_id'] : '';
578	
579	  switch (name) {
580	    // --- Mutation tools ---
581	    case 'ledger_begin_work':
582	    case 'ledger_start_pipeline': {
583	      const type = typeof a['type'] === 'string' ? a['type'] : '';
584	      const role = typeof a['agent_role'] === 'string' ? a['agent_role'] : '';
585	      if (!wp) return [];
586	      return [`↳ ${wp} — ${type} (${role})`];
587	    }
588	
589	    case 'ledger_complete_pipeline': {
590	      const type = typeof a['type'] === 'string' ? a['type'] : '';
591	      const status = typeof a['status'] === 'string' ? a['status'] : '';
592	      if (!wp) return [];
593	      const detail = [`↳ ${wp} ${type} → ${status}`];
594	      // Append first summary bullet if available.
595	      const summary = a['summary'];
596	      let firstItem: string | null = null;
597	      if (typeof summary === 'string' && summary.trim()) {
598	        firstItem = summary.trim().split('\n')[0] ?? null;
599	      } else if (Array.isArray(summary) && summary.length > 0) {
600	        const first = summary[0];
601	        if (typeof first === 'string' && first.trim()) firstItem = first.trim();
602	      }
603	      if (firstItem) detail.push(`↳ ${firstItem}`);
604	      return detail;
605	    }
606	
607	    case 'ledger_cancel_pipeline': {
608	      const type = typeof a['type'] === 'string' ? a['type'] : '';
609	      const reason = typeof a['reason'] === 'string' ? a['reason'] : '';
610	      if (!wp) return [];
611	      return [`↳ ${wp} ${type} — ${reason}`];
612	    }
613	
614	    case 'ledger_claim_work_package': {
615	      const agent = typeof a['agent'] === 'string' ? a['agent'] : '';
616	      if (!wp) return [];
617	      return [`↳ ${wp} → ${agent}`];
618	    }
619	
620	    case 'ledger_update_work_package_status': {
621	      const status = typeof a['status'] === 'string' ? a['status'] : '';
622	      if (!wp) return [];
623	      return [`↳ ${wp} → ${status}`];
624	    }
625	
626	    case 'ledger_update_pipeline_progress': {
627	      const type = typeof a['type'] === 'string' ? a['type'] : '';
628	      const summary = a['summary'];
629	      let firstItem = '';
630	      if (typeof summary === 'string') firstItem = summary.trim().split('\n')[0] ?? '';
631	      else if (Array.isArray(summary) && summary.length > 0) {
632	        const first = summary[0];
633	        if (typeof first === 'string') firstItem = first.trim();
634	      }
635	      if (!wp) return [];
636	      return [`↳ ${wp} ${type} — ${firstItem}`];
637	    }
638	
639	    case 'ledger_update_acceptance_criteria': {
640	      const ops = a['operations'];
641	      const n = Array.isArray(ops) ? ops.length : 0;
642	      if (!wp) return [];
643	      return [`↳ ${wp} (${n} operations)`];
644	    }
645	
646	    case 'ledger_add_project_comment': {
647	      const type = typeof a['type'] === 'string' ? a['type'] : '';
648	      const priority = typeof a['priority'] === 'string' ? a['priority'] : '';
649	      const note = typeof a['note'] === 'string' ? a['note'] : '';
650	      const firstNoteLine = note.split('\n')[0] ?? '';

651	      return [`↳ ${type} (${priority}): ${firstNoteLine}`];
652	    }
653	
654	    // --- Query tools ---
655	    case 'ledger_get_next_action': {
656	      const role = typeof a['agent_role'] === 'string' ? a['agent_role'] : '';
657	      return role ? [`↳ ${role}`] : [];
658	    }
659	
660	    case 'ledger_get_work_package': {
661	      return wp ? [`↳ ${wp}`] : [];
662	    }
663	
664	    case 'ledger_get_handoff_status': {
665	      const agent = typeof a['current_agent'] === 'string' ? a['current_agent'] : '';
666	      return agent ? [`↳ ${agent}`] : [];
667	    }
668	
669	    case 'ledger_search_insights': {
670	      const query = typeof a['query'] === 'string' ? a['query'] : '';
671	      return query ? [`↳ "${query}"`] : [];
672	    }
673	
674	    // --- No-detail query tools ---
675	    case 'ledger_get_project_status':
676	    case 'ledger_list_work_packages':
677	      return [];
678	
679	    // --- Other ledger_* tools (no detail, but always shown via header) ---
680	    default:
681	      return [];
682	  }
683	}
