688	
689	/**
690	 * Returns 0–N `↳ …` detail lines for a given tool call.  Dispatches to the
691	 * appropriate per-family formatter helper.
692	 *
693	 * @param name         Tool name.
694	 * @param args         Parsed tool arguments (object or null).
695	 * @param resultEntry  Optional result index entry for tools needing inline results.
696	 */
697	function getToolDetailLines(
698	  name: string,
699	  args: unknown,
700	  resultEntry?: { toolName: string; content: string },
701	): string[] {
702	  // File family
703	  if (name === 'edit_file' || name === 'write_file' || name === 'read_file') {
704	    return formatFileToolDetail(args);
705	  }
706	  // Execution family
707	  if (name === 'execute') {
708	    return formatExecuteDetail(args, resultEntry);
709	  }
710	  // Task family
711	  if (name === 'task') {
712	    return formatTaskDetail(args, resultEntry);
713	  }
714	  // Todo family
715	  if (name === 'write_todos') {
716	    return formatWriteTodosDetail(args);
717	  }
718	  // Search family — no detail line
719	  if (name === 'glob' || name === 'grep' || name === 'ls') {
720	    return [];
721	  }
722	  // Ledger family
723	  if (name.startsWith('ledger_')) {
724	    return formatLedgerToolDetail(name, args);
725	  }
726	  // Default / unknown — no detail line, header always shown by caller
727	  return [];
728	}
