730	// ---------------------------------------------------------------------------
731	// Dialogue rendering — message walker
732	// ---------------------------------------------------------------------------
733	
734	/**
735	 * Renders a list of merged messages in dialogue style.
736	 *
737	 * - AI messages: text content as plain paragraphs; tool calls as `Tool call: \`name\`` lines.
738	 * - ToolMessages: skipped (results already consumed inline for `execute` and `task`).
739	 * - All other message types (Human, System, …): skipped silently.
740	 */
741	function renderDialogueMessages(
742	  messages: MergedMessage[],
743	  toolResultIndex: Map<string, { toolName: string; content: string }>,
744	): string[] {
745	  const lines: string[] = [];
746	
747	  for (const msg of messages) {
748	    const msgType = msg.type.toLowerCase();
749	
750	    // Only AI messages contribute dialogue output.
751	    if (
752	      msgType !== 'ai' &&
753	      msgType !== 'aimessage' &&
754	      msgType !== 'aimessagechunk'
755	    ) {
756	      continue; // Skip Human, System, ToolMessage, etc.
757	    }
758	
759	    // Render text content as plain paragraphs.
760	    const contentStr = renderContent(msg.content).trim();
761	    if (contentStr) {
762	      lines.push(contentStr);
763	      lines.push('');
764	    }
765	
766	    // Render each tool call as a `Tool call: \`name\`` header + detail lines.
767	    for (const tc of msg.tool_calls) {
768	      const toolName = tc.name || 'unknown_tool';
769	      lines.push(`Tool call: \`${toolName}\``);
770	
771	      // Parse args once.
772	      let parsedArgs: unknown = null;
773	      try {
774	        parsedArgs = tc.args ? JSON.parse(tc.args) : null;
775	      } catch {
776	        parsedArgs = null;
777	      }
778	
779	      // Look up result entry (only populated for `execute` and `task`).
780	      const resultEntry = tc.id ? toolResultIndex.get(tc.id) : undefined;
781	
782	      const detailLines = getToolDetailLines(toolName, parsedArgs, resultEntry);
783	      lines.push(...detailLines);
784	      lines.push('');
785	    }
786	  }
787	
788	  return lines;
789	}
