818	// ---------------------------------------------------------------------------
819	// Public API — dialogue renderer
820	// ---------------------------------------------------------------------------
821	
822	/**
823	 * Parses a JSONL chunk file and renders its contents in a clean, chat-like
824	 * dialogue format.
825	 *
826	 * Differences from `renderChunksToMarkdown`:
827	 * - No `# Dialogue` document header or metadata table.
828	 * - No `## Role` headings — AI text appears as plain paragraphs.
829	 * - Tool calls are rendered as `Tool call: \`name\`` with a compact detail line
830	 *   instead of a full JSON fenced block.
831	 * - ToolMessages are hidden; `execute` and `task` results are shown inline with
832	 *   their tool call.
833	 * - No token-usage footer.
834	 *
835	 * @param jsonlContent  Raw JSONL string (e.g. the content of a `.jsonl` chunk file).
836	 * @returns             A Markdown string (always ends with a trailing `\n`).
837	 *                      Returns `*No dialogue recorded.*\n` for empty or header-only input.
838	 */
839	export function renderChunksToDialogue(jsonlContent: string): string {
840	  // --- Parse JSONL content (header validation + line parsing) ---
841	  const records = parseJsonlContent(jsonlContent);
842	
843	  // --- Accumulate chunks into merged messages per namespace ---
844	  const nsMap = accumulateChunks(records);
845	
846	  if (nsMap.size === 0) {
847	    return '*No dialogue recorded.*\n';
848	  }
849	
850	  // --- Build correlation indexes ---

 851	  const toolCallIndex = buildToolCallIndex(nsMap);
 852	  const toolResultIndex = buildToolResultIndex(nsMap, toolCallIndex);
 853	
 854	  // --- Render per namespace (main agent first, sub-agents next) ---
 855	  const lines: string[] = [];
 856	
 857	  const mainMessages = nsMap.get('');
 858	  if (mainMessages && mainMessages.length > 0) {
 859	    lines.push(...renderDialogueNamespaceBlock('', mainMessages, toolResultIndex, false));
 860	  }
 861	
 862	  for (const [nsKey, messages] of nsMap.entries()) {
 863	    if (nsKey === '') continue;
 864	    if (messages.length > 0) {
 865	      lines.push(...renderDialogueNamespaceBlock(nsKey, messages, toolResultIndex, true));
 866	    }
 867	  }
 868	
 869	  // Remove any trailing blank lines before adding the final newline.
 870	  while (lines.length > 0 && lines[lines.length - 1] === '') {
 871	    lines.pop();
 872	  }
 873	
 874	  return lines.join('\n') + '\n';
 875	}
