 877	// ---------------------------------------------------------------------------
 878	// Structured rendering — public types
 879	// ---------------------------------------------------------------------------
 880	
 881	/**
 882	 * A single dialogue block in the structured representation returned by
 883	 * `renderChunksToStructured()`.
 884	 *
 885	 * Discriminated union on the `type` field:
 886	 *  - `text`             — AI prose content (no JSON or tool-call data mixed in).
 887	 *  - `tool-call`        — One tool invocation: name, detail lines, parsed args,
 888	 *                         and an optional embedded ToolMessage result for
 889	 *                         non-inline tools (not `execute`/`task`).
 890	 *  - `subagent-heading` — Heading that marks the start of a sub-agent namespace.
 891	 *  - `checklist`        — A `write_todos` invocation rendered as a typed item list.
 892	 */
 893	export type DialogueBlock =
 894	  | { type: 'text'; content: string }
 895	  | {
 896	      type: 'tool-call';
 897	      name: string;
 898	      detailLines: string[];
 899	      args: unknown;
 900	      result?: { content: string };
 901	    }
 902	  | { type: 'subagent-heading'; label: string }
 903	  | {
 904	      type: 'checklist';
 905	      items: Array<{ content: string; status: string; checked: boolean }>;
 906	    };
