 908	// ---------------------------------------------------------------------------
 909	// Structured rendering — private helpers
 910	// ---------------------------------------------------------------------------
 911	
 912	/**
 913	 * Builds a map from toolCallId → { toolName, content } by scanning ALL
 914	 * ToolMessage entries across all namespaces.  Unlike `buildToolResultIndex()`,
 915	 * no tool-name filter is applied — every ToolMessage is indexed.
 916	 *
 917	 * Used by `renderChunksToStructured()` so that non-inline tool results
 918	 * (e.g. `read_file`, `glob`, `ledger_*`) can be embedded in their tool-call
 919	 * blocks via the `result` field.
 920	 */
 921	function buildFullToolResultIndex(
 922	  nsMap: Map<NamespaceKey, MergedMessage[]>,
 923	  toolCallIndex: Map<string, string>,
 924	): Map<string, { toolName: string; content: string }> {
 925	  const index = new Map<string, { toolName: string; content: string }>();
 926	
 927	  for (const messages of nsMap.values()) {
 928	    for (const msg of messages) {
 929	      const msgType = msg.type.toLowerCase();
 930	      if (msgType !== 'tool' && msgType !== 'toolmessage') continue;
 931	      const tcId = msg.tool_call_id;
 932	      if (!tcId) continue;
 933	
 934	      const toolName = toolCallIndex.get(tcId) ?? '';
 935	      const content = renderContent(msg.content);
 936	      index.set(tcId, { toolName, content });
 937	    }
 938	  }
 939	
 940	  return index;
 941	}
 942	
 943	/**
 944	 * Parses `write_todos` args into a typed checklist item array.
 945	 */
 946	function buildChecklistItems(
 947	  args: unknown,
 948	): Array<{ content: string; status: string; checked: boolean }> {
 949	  if (!args || typeof args !== 'object' || Array.isArray(args)) return [];
 950	  const a = args as Record<string, unknown>;
 951	  const todos = a['todos'];
 952	  if (!Array.isArray(todos)) return [];
 953	
 954	  return todos.map((todo: unknown) => {
 955	    if (!todo || typeof todo !== 'object' || Array.isArray(todo)) {
 956	      return { content: '(unknown)', status: '', checked: false };
 957	    }
 958	    const t = todo as Record<string, unknown>;
 959	    const content = typeof t['content'] === 'string' ? t['content'] : '(unknown)';
 960	    const status = typeof t['status'] === 'string' ? t['status'] : '';
 961	    const checked = status === 'completed';
 962	    return { content, status, checked };
 963	  });
 964	}
 965	
 966	/**
 967	 * Walks a list of merged messages and emits DialogueBlock objects.
 968	 *
 969	 * - AI messages: text content → `text` block; tool calls → `tool-call` or `checklist`.
 970	 * - Inline tools (`execute`, `task`): result summary stays in `detailLines`.
 971	 * - Non-inline tools: result (if any) is embedded in the `result` field.
 972	 * - ToolMessages, Human, System: skipped.
 973	 */
 974	function renderMessagesToStructuredBlocks(
 975	  messages: MergedMessage[],
 976	  fullToolResultIndex: Map<string, { toolName: string; content: string }>,
 977	): DialogueBlock[] {
 978	  const blocks: DialogueBlock[] = [];
 979	
 980	  for (const msg of messages) {
 981	    const msgType = msg.type.toLowerCase();
 982	    if (
 983	      msgType !== 'ai' &&
 984	      msgType !== 'aimessage' &&
 985	      msgType !== 'aimessagechunk'
 986	    ) {
 987	      continue;
 988	    }
 989	
 990	    // AI text content → text block.
 991	    const contentStr = renderContent(msg.content).trim();
 992	    if (contentStr) {
 993	      blocks.push({ type: 'text', content: contentStr });
 994	    }
 995	
 996	    // Tool calls.
 997	    for (const tc of msg.tool_calls) {
 998	      const toolName = tc.name || 'unknown_tool';
 999	
1000	      let parsedArgs: unknown = null;
1001	      try {
1002	        parsedArgs = tc.args ? JSON.parse(tc.args) : null;
1003	      } catch {
1004	        parsedArgs = null;
1005	      }
1006	
1007	      if (toolName === 'write_todos') {
1008	        // write_todos → checklist block (not a generic tool-call block).
1009	        blocks.push({ type: 'checklist', items: buildChecklistItems(parsedArgs) });
1010	      } else {
1011	        const isInline = INLINE_RESULT_TOOLS.has(toolName);
1012	        const resultEntry = tc.id ? fullToolResultIndex.get(tc.id) : undefined;
1013	
1014	        // Inline tools (execute, task): pass resultEntry to getToolDetailLines so
1015	        // the result summary appears in detailLines — matching the dialogue renderer.
1016	        // All other tools: detailLines come from args only; result goes in result field.
1017	        const detailLines = getToolDetailLines(
1018	          toolName,
1019	          parsedArgs,
1020	          isInline ? resultEntry : undefined,
1021	        );
1022	
1023	        if (!isInline && resultEntry) {
1024	          blocks.push({
1025	            type: 'tool-call',
1026	            name: toolName,
1027	            detailLines,
1028	            args: parsedArgs,
1029	            result: { content: resultEntry.content },
1030	          });
1031	        } else {
1032	          blocks.push({
1033	            type: 'tool-call',
1034	            name: toolName,
1035	            detailLines,
1036	            args: parsedArgs,
1037	          });
1038	        }
1039	      }
1040	    }
1041	  }
1042	
1043	  return blocks;
1044	}
