1046	/**
1047	 * Collects DialogueBlocks for a namespace block.
1048	 * For sub-agents, prepends a `subagent-heading` block before the content blocks.
1049	 */
1050	function collectStructuredNamespaceBlocks(

1051	  nsKey: NamespaceKey,
1052	  messages: MergedMessage[],
1053	  fullToolResultIndex: Map<string, { toolName: string; content: string }>,
1054	  isSubagent: boolean,
1055	): DialogueBlock[] {
1056	  const blocks: DialogueBlock[] = [];
1057	
1058	  if (isSubagent) {
1059	    blocks.push({ type: 'subagent-heading', label: namespaceLabel(nsKey) });
1060	  }
1061	
1062	  blocks.push(...renderMessagesToStructuredBlocks(messages, fullToolResultIndex));
1063	  return blocks;
1064	}
