1070	/**
1071	 * Parses a JSONL chunk file and returns a structured array of `DialogueBlock`
1072	 * objects representing the conversation.
1073	 *
1074	 * This is the structured alternative to `renderChunksToDialogue()`: instead of
1075	 * a flat Markdown string the caller receives typed block objects that give the
1076	 * frontend full control over rendering (collapsible tool calls, interactive
1077	 * checklists, inline results).
1078	 *
1079	 * Block types:
1080	 *  - `text`             — AI prose only; no JSON or tool-call data mixed in.
1081	 *  - `tool-call`        — Tool name, `getToolDetailLines()` detail lines, parsed
1082	 *                         args, and an optional `result.content` for non-inline tools.
1083	 *  - `subagent-heading` — Marks the start of a sub-agent namespace block.
1084	 *  - `checklist`        — `write_todos` items with `content`, `status`, `checked`.
1085	 *
1086	 * ToolMessage results for non-inline tools (not `execute`/`task`) are embedded
1087	 * in the `result` field of the corresponding tool-call block.  Inline tool
1088	 * results remain in `detailLines` (matching the dialogue renderer).
1089	 *
1090	 * @param jsonlContent  Raw JSONL string (e.g. the content of a `.jsonl` chunk file).
1091	 * @returns             Array of `DialogueBlock` objects; empty array for empty input.
1092	 */
1093	export function renderChunksToStructured(jsonlContent: string): DialogueBlock[] {
1094	  // --- Parse JSONL content (header validation + line parsing) ---
1095	  const records = parseJsonlContent(jsonlContent);
1096	
1097	  // --- Accumulate chunks into merged messages per namespace ---
1098	  const nsMap = accumulateChunks(records);
1099	
1100	  if (nsMap.size === 0) {
1101	    return [];
1102	  }
1103	
1104	  // --- Build correlation indexes ---
1105	  const toolCallIndex = buildToolCallIndex(nsMap);
1106	  const fullToolResultIndex = buildFullToolResultIndex(nsMap, toolCallIndex);
1107	
1108	  // --- Collect blocks (main agent first, sub-agents next) ---
1109	  const blocks: DialogueBlock[] = [];
1110	
1111	  const mainMessages = nsMap.get('');
1112	  if (mainMessages && mainMessages.length > 0) {
1113	    blocks.push(...collectStructuredNamespaceBlocks('', mainMessages, fullToolResultIndex, false));
1114	  }
1115	
1116	  for (const [nsKey, messages] of nsMap.entries()) {
1117	    if (nsKey === '') continue;
1118	    if (messages.length > 0) {
1119	      blocks.push(...collectStructuredNamespaceBlocks(nsKey, messages, fullToolResultIndex, true));
1120	    }
1121	  }
1122	
1123	  return blocks;
1124	}
