1126	// ---------------------------------------------------------------------------
1127	// Text-only rendering — private helpers
1128	// ---------------------------------------------------------------------------
1129	
1130	/**
1131	 * Iterates AI messages and extracts prose text only (no tool calls, no tool
1132	 * results).  Calls `renderContent(msg.content).trim()` on each AI message and
1133	 * joins non-empty results with `'\n\n'`.
1134	 *
1135	 * Used exclusively by `renderChunksToText()`.
1136	 */
1137	function extractTextFromMessages(messages: MergedMessage[]): string {
1138	  const parts: string[] = [];
1139	  for (const msg of messages) {
1140	    const msgType = msg.type.toLowerCase();
1141	    if (
1142	      msgType !== 'ai' &&
1143	      msgType !== 'aimessage' &&
1144	      msgType !== 'aimessagechunk'
1145	    ) {
1146	      continue;
1147	    }
1148	    const text = renderContent(msg.content).trim();
1149	    if (text) {
1150	      parts.push(text);
