1156	// ---------------------------------------------------------------------------
1157	// Public API — text-only renderer
1158	// ---------------------------------------------------------------------------
1159	
1160	/**
1161	 * Parses a JSONL chunk file and returns a prose-only Markdown string
1162	 * containing only the AI turns' text content — no tool-call JSON, no tool
1163	 * results.
1164	 *
1165	 * Output format:
1166	 *  - **Single-namespace** files: flat prose paragraphs, no section headers.
1167	 *  - **Dual-namespace** files (outer + inner agent): two sections labelled
1168	 *    `## Outer Agent` and `## Inner Agent` with prose beneath each.
1169	 *
1170	 * This renderer shares its `.md` output format with the CLI extraction script
1171	 * (`scripts/extract-dialogue.js`) so that either tool can prime the on-disk
1172	 * cache that the backend's `/chunks/:filename/text` endpoint uses.
1173	 *
1174	 * @param jsonlContent  Raw JSONL string (e.g. the content of a `.jsonl` chunk file).
1175	 * @returns             A Markdown string (always ends with a trailing `\n`).
1176	 *                      Returns `'*No dialogue recorded.*\n'` for empty input or
1177	 *                      when all AI turns contain no text content.
1178	 */
1179	export function renderChunksToText(jsonlContent: string): string {
1180	  // --- Parse JSONL content (header validation + line parsing) ---
1181	  const records = parseJsonlContent(jsonlContent);
1182	
1183	  // --- Accumulate chunks into merged messages per namespace ---
1184	  const nsMap = accumulateChunks(records);
1185	
1186	  if (nsMap.size === 0) {
1187	    return '*No dialogue recorded.*\n';
1188	  }
1189	
1190	  // --- Detect whether sub-agent namespaces are present ---
1191	  const hasSubAgents = [...nsMap.keys()].some(k => k !== '');
1192	
1193	  if (!hasSubAgents) {
1194	    // Single-namespace: flat prose, no section headers.
1195	    const mainMessages = nsMap.get('') ?? [];
1196	    const text = extractTextFromMessages(mainMessages);
1197	    if (!text) {
1198	      return '*No dialogue recorded.*\n';
1199	    }
1200	    return text + '\n';
1201	  }
1202	
1203	  // --- Dual-namespace: labelled sections ---
1204	  const mainMessages = nsMap.get('') ?? [];
1205	  const outerText = extractTextFromMessages(mainMessages);
1206	
1207	  const innerTexts: string[] = [];
1208	  for (const [nsKey, messages] of nsMap.entries()) {
1209	    if (nsKey === '') continue;
1210	    innerTexts.push(extractTextFromMessages(messages));
1211	  }
1212	
1213	  // If all sections are empty, return the standard empty sentinel.
1214	  if (!outerText && innerTexts.every(t => !t)) {
1215	    return '*No dialogue recorded.*\n';
1216	  }
1217	
1218	  const sections: string[] = [];
1219	  sections.push('## Outer Agent\n\n' + (outerText || '*No dialogue recorded.*'));
1220	  for (const innerText of innerTexts) {
1221	    sections.push('## Inner Agent\n\n' + (innerText || '*No dialogue recorded.*'));
1222	  }
1223	
1224	  return sections.join('\n\n') + '\n';
1225	}

